// Underworld: the custom dimension, the hallucinogenic rock, the terrain generation
// and the skeletal mobs. Generated by tools/underworld.py (the terrain is built by gen.js).
import { BlockPermutation, BlockVolume, ItemStack, system, world } from "@minecraft/server";
import { buildCell, cellOf, CELL, HALF, H, LAVA } from "./gen.js";

const CFG = __CONFIG__;
const DIM = CFG.dimension;
const OVERWORLD = "minecraft:overworld";

// ------------------------------------------------------------ the dimension
system.beforeEvents.startup.subscribe((ev) => {
  ev.dimensionRegistry.registerCustomDimension(DIM);
});

function underworld() {
  return world.getDimension(DIM);
}

function seed() {
  let s = world.getDynamicProperty("underworld:seed");
  if (typeof s !== "number") {
    s = Math.floor(Math.random() * 2147483647);
    world.setDynamicProperty("underworld:seed", s);
  }
  return s;
}

// ------------------------------------------------------------ generation
// The dimension is generated one cell (4x4 chunks) at a time, around the players.
const perms = new Map();
function perm(block) {
  const id = typeof block === "string" ? block : block.id;
  const key = typeof block === "string" ? block : `${id}|${JSON.stringify(block.states)}`;
  if (!perms.has(key)) {
    let p = null;
    try {
      p = BlockPermutation.resolve(id, typeof block === "string" ? undefined : block.states);
    } catch {
      try {
        p = BlockPermutation.resolve(id);
      } catch {
        console.warn(`[Underworld] bloque desconocido: ${key}`);
      }
    }
    perms.set(key, p);
  }
  return perms.get(key);
}

function apply(dim, op) {
  if (op[0] === "f") {
    const [, x1, y1, z1, x2, y2, z2, b] = op;
    const p = perm(b);
    if (p) dim.fillBlocks(new BlockVolume({ x: x1, y: y1, z: z1 }, { x: x2, y: y2, z: z2 }), p);
    return;
  }
  const [, x, y, z, b, items] = op;
  const p = perm(b);
  if (!p) return;
  const block = dim.getBlock({ x, y, z });
  if (!block) throw new Error("unloaded");
  block.setPermutation(p);
  if (op[0] === "c") {
    const inv = block.getComponent("minecraft:inventory")?.container;
    if (!inv) return;
    for (const [id, count] of items) {
      try {
        inv.addItem(new ItemStack(id, count));
      } catch {}
    }
  }
}

// One job per cell: first the terrain is computed, then its blocks are placed. Both
// parts pause often, so the game spreads them over as many ticks as it needs.
function* cellJob(dim, cx, cz, done) {
  let failed = 0, total = 1;
  try {
    const { ops } = yield* buildCell(cx, cz, seed());
    total = ops.length;
    let n = 0;
    for (const op of ops) {
      try {
        apply(dim, op);
      } catch {
        failed++;
      }
      if (++n % CFG.opsPerStep === 0) yield;
    }
  } catch (e) {
    console.warn(`[Underworld] error generando ${cx},${cz}: ${e}`);
    failed = total;
  }
  done(failed <= total * 0.02);
}

const cellKey = (cx, cz) => `underworld:cell:${cx}:${cz}`;
const isBuilt = (cx, cz) => world.getDynamicProperty(cellKey(cx, cz)) === true;
const building = new Map(); // key -> promise
const retryAt = new Map(); // key -> tick: cells that could not be loaded wait a little

function areaId(what, a, b = 0) {
  return `underworld_${what}_${a}_${b}`.replace(/-/g, "m");
}

async function loadArea(dim, id, from, to) {
  try {
    await world.tickingAreaManager.createTickingArea(id, { dimension: dim, from, to });
    return true;
  } catch (e) {
    console.warn(`[Underworld] no se pudo crear la zona de carga ${id}: ${e}`);
    return false;
  }
}

function dropArea(id) {
  try {
    world.tickingAreaManager.removeTickingArea(id);
  } catch {}
}

function generateCell(cx, cz) {
  const key = cellKey(cx, cz);
  if (isBuilt(cx, cz)) return Promise.resolve(true);
  if (building.has(key)) return building.get(key);
  const job = (async () => {
    const dim = underworld();
    const x0 = cx * CELL - HALF, x1 = x0 + CELL - 1, z0 = cz * CELL - HALF, z1 = z0 + CELL - 1;
    const id = areaId("gen", cx, cz);
    const loaded = await loadArea(dim, id, { x: x0, y: 0, z: z0 }, { x: x1, y: 0, z: z1 });
    try {
      // without a ticking area, only build when the players already keep the whole cell loaded
      if (!loaded && (!dim.getBlock({ x: x0, y: 8, z: z0 }) || !dim.getBlock({ x: x1, y: 8, z: z1 }))) {
        retryAt.set(key, system.currentTick + 200);
        return false;
      }
      const ok = await new Promise((resolve) => system.runJob(cellJob(dim, cx, cz, resolve)));
      if (ok) world.setDynamicProperty(key, true);
      else retryAt.set(key, system.currentTick + 100);
      return ok;
    } finally {
      if (loaded) dropArea(id);
    }
  })();
  building.set(key, job);
  job.catch((e) => console.warn(`[Underworld] error generando ${cx},${cz}: ${e}`)).finally(() => building.delete(key));
  return job;
}

function playersHere() {
  return world.getPlayers().filter((p) => p.dimension.id === DIM);
}

// Queue: the cells around the players in the dimension, nearest first, one at a time.
let busy = false;
system.runInterval(() => {
  if (busy) return;
  let best = null;
  for (const player of playersHere()) {
    const { x, z } = player.location;
    const pcx = cellOf(x), pcz = cellOf(z);
    for (let dx = -CFG.radius; dx <= CFG.radius; dx++)
      for (let dz = -CFG.radius; dz <= CFG.radius; dz++) {
        const cx = pcx + dx, cz = pcz + dz;
        if (isBuilt(cx, cz) || (retryAt.get(cellKey(cx, cz)) ?? 0) > system.currentTick) continue;
        // distance from the player to the centre of the cell
        const d = (cx * CELL - x) ** 2 + (cz * CELL - z) ** 2;
        if (!best || d < best.d) best = { cx, cz, d };
      }
  }
  if (!best) return;
  busy = true;
  generateCell(best.cx, best.cz).catch(() => {}).finally(() => (busy = false));
}, 5);

// Nobody walks off the edge of the world: a player who reaches a cell that is still
// forming is taken back to the last firm ground they stood on.
const lastSafe = new Map();
system.runInterval(() => {
  for (const player of playersHere()) {
    try {
      const loc = player.location;
      if (isBuilt(cellOf(loc.x), cellOf(loc.z))) {
        if (player.isOnGround) lastSafe.set(player.id, { x: loc.x, y: loc.y, z: loc.z });
        continue;
      }
      const safe = lastSafe.get(player.id);
      if (!safe) continue;
      player.teleport(safe, { dimension: underworld() });
      player.onScreenDisplay.setActionBar("§3El Underworld aún se está formando ahí delante...");
    } catch {}
  }
}, 5);

// ------------------------------------------------------------ fog
system.runInterval(() => {
  for (const player of world.getPlayers()) {
    try {
      const inside = player.dimension.id === DIM, has = player.getDynamicProperty("underworld:fog") === true;
      if (inside === has) continue;
      player.runCommand(inside ? `fog @s push ${CFG.fog} underworld` : "fog @s remove underworld");
      player.setDynamicProperty("underworld:fog", inside);
    } catch {}
  }
}, 20);

// ------------------------------------------------------------ only skeletal mobs
const KEEP = new Set(["minecraft:player", "minecraft:armor_stand"]);
const SKELETAL = new Set(CFG.skeletal);

function isSkeletal(entity) {
  if (SKELETAL.has(entity.typeId)) return true;
  try {
    return entity.matches({ families: ["skeleton"] });   // also the skeletons of other add-ons
  } catch {
    return false;
  }
}

function unwanted(entity) {
  return !KEEP.has(entity.typeId) && entity.getComponent("minecraft:health") !== undefined && !isSkeletal(entity);
}

world.afterEvents.entitySpawn.subscribe(({ entity }) => {
  try {
    if (entity.dimension.id === DIM && unwanted(entity)) entity.remove();
  } catch {}
});

system.runInterval(() => {
  try {
    for (const e of underworld().getEntities({ excludeTypes: ["minecraft:player"] })) if (unwanted(e)) e.remove();
  } catch {}
}, 100);

// The dimension has no biome of its own to spawn mobs, so the script does it: now and
// then, some skeletal mob appears on the floor of a cavern near each player.
const NO_FLOOR = new Set(["minecraft:air", "minecraft:lava", "minecraft:flowing_lava", "minecraft:soul_fire",
  "minecraft:fire", "minecraft:soul_lantern", "minecraft:skeleton_skull", "minecraft:cobbled_deepslate_wall",
  "minecraft:chest"]);
const isAir = (b) => b?.typeId === "minecraft:air";

function pickMob(floorId) {
  const table = floorId === "minecraft:soul_sand" || floorId === "minecraft:soul_soil" ? CFG.mobs.soul
    : floorId === "minecraft:bone_block" ? CFG.mobs.bone : CFG.mobs.slate;
  let total = 0;
  for (const [, w] of table) total += w;
  let k = Math.random() * total;
  for (const [id, w] of table) if ((k -= w) < 0) return id;
  return table[0][0];
}

function trySpawn(dim, player) {
  const p = player.location;
  const ang = Math.random() * Math.PI * 2, dist = CFG.spawnMin + Math.random() * (CFG.spawnMax - CFG.spawnMin);
  const x = Math.floor(p.x + Math.cos(ang) * dist), z = Math.floor(p.z + Math.sin(ang) * dist);
  let y = Math.min(H - 4, Math.max(LAVA + 3, Math.floor(p.y + (Math.random() - 0.5) * 20)));
  let block = dim.getBlock({ x, y, z });
  for (let i = 0; block && i < 18 && y > LAVA + 1; i++, y--) {
    const below = block.below();
    if (isAir(block) && isAir(block.above()) && isAir(block.above(2)) && below && !NO_FLOOR.has(below.typeId)) {
      const id = pickMob(below.typeId);
      for (let n = Math.random() < 0.3 ? 2 : 1; n > 0; n--) {
        try {
          dim.spawnEntity(id, { x: x + 0.5, y, z: z + 0.5 });
        } catch {}
      }
      return true;
    }
    block = below;
  }
  return false;
}

system.runInterval(() => {
  let dim;
  try {
    dim = underworld();
  } catch {
    return;
  }
  for (const player of playersHere()) {
    try {
      const near = dim.getEntities({ location: player.location, maxDistance: 56, excludeTypes: ["minecraft:player"] })
        .filter(isSkeletal).length;
      if (near >= CFG.mobCap) continue;
      for (let t = 0; t < 6; t++) if (trySpawn(dim, player)) break;
    } catch {}
  }
}, CFG.spawnEvery);

// ------------------------------------------------------------ the hallucinogenic rock
const traveling = new Set();

// A place to stand near (x, z): rock below, two blocks of air, as close as possible.
function findSpot(dim, bx, bz, nearY) {
  let best = null;
  for (let r = 0; r <= 14 && !best; r++) {
    for (let dx = -r; dx <= r; dx++)
      for (let dz = -r; dz <= r; dz++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
        let block = dim.getBlock({ x: bx + dx, y: LAVA + 2, z: bz + dz });
        let run = 0;   // blocks of air seen above the last floor
        let floorY = null;
        for (let y = LAVA + 2; block && y < H - 2; y++, block = block.above()) {
          if (isAir(block)) {
            if (floorY !== null && ++run === 2) {
              const d = Math.abs(floorY + 1 - nearY);
              if (!best || d < best.d) best = { x: bx + dx, y: floorY + 1, z: bz + dz, d };
            }
          } else {
            run = 0;
            floorY = NO_FLOOR.has(block.typeId) ? null : y;
          }
        }
      }
  }
  return best;
}

function tell(player, text) {
  try {
    player.onScreenDisplay.setActionBar(text);
  } catch {}
}

async function enter(player, from) {
  const bx = Math.floor(from.x), bz = Math.floor(from.z);
  const dim = underworld();
  const id = areaId("in", player.id);
  const ok = await loadArea(dim, id, { x: bx - 16, y: 0, z: bz - 16 }, { x: bx + 16, y: 0, z: bz + 16 });
  try {
    let spot = findSpot(dim, bx, bz, 40);
    if (!spot) {
      // solid rock all around: open a small pocket
      spot = { x: bx, y: 40, z: bz };
      dim.getBlock({ x: bx, y: 39, z: bz })?.setPermutation(perm("minecraft:deepslate"));
      for (const y of [40, 41]) dim.getBlock({ x: bx, y, z: bz })?.setPermutation(perm("minecraft:air"));
    }
    const loc = { x: spot.x + 0.5, y: spot.y, z: spot.z + 0.5 };
    lastSafe.set(player.id, loc);
    player.teleport(loc, { dimension: dim });
  } finally {
    if (ok) system.runTimeout(() => dropArea(id), 100);
  }
  player.onScreenDisplay.setTitle("§3Underworld", { subtitle: "§7donde descansan los huesos", fadeInDuration: 20, stayDuration: 60, fadeOutDuration: 20 });
}

async function leave(player) {
  let back = null;
  try {
    back = JSON.parse(player.getDynamicProperty("underworld:back") ?? "null");
  } catch {}
  const dim = world.getDimension(OVERWORLD);
  const id = areaId("out", player.id);
  const loc = back ? { x: back.x, y: back.y, z: back.z } : null;
  const spawn = world.getDefaultSpawnLocation();
  const at = loc ?? { x: spawn.x + 0.5, y: 0, z: spawn.z + 0.5 };
  const ok = await loadArea(dim, id, { x: at.x - 4, y: 0, z: at.z - 4 }, { x: at.x + 4, y: 0, z: at.z + 4 });
  try {
    if (!loc) {
      // no position saved (the player got here some other way): the world spawn
      const top = dim.getTopmostBlock({ x: at.x, z: at.z });
      at.y = top ? top.y + 1 : 100;
    }
    player.teleport(at, { dimension: dim });
  } finally {
    if (ok) system.runTimeout(() => dropArea(id), 100);
  }
}

async function trip(player, leaving) {
  const from = player.dimension.id, start = player.location;
  const ticks = CFG.trance * 20;
  player.addEffect("blindness", ticks + 60, { showParticles: false });
  player.addEffect("nausea", ticks + 120, { showParticles: false });
  player.playSound("portal.trigger", { volume: 0.6, pitch: 0.6 });
  tell(player, "§5La roca te nubla los sentidos...");
  // the cavern you will wake up in starts forming while the rock takes effect
  if (!leaving) generateCell(cellOf(start.x), cellOf(start.z)).catch(() => {});
  await system.waitTicks(ticks);
  if (!player.isValid || player.dimension.id !== from) return;   // left the game, died...
  if (leaving) {
    player.addEffect("blindness", 50, { showParticles: false });
    await leave(player);
  } else {
    let ok = false;
    for (let t = 0; !ok && t < 4 && player.isValid; t++) {
      if (t) await system.waitTicks(40);
      player.addEffect("blindness", 100, { showParticles: false });
      ok = await generateCell(cellOf(player.location.x), cellOf(player.location.z));
    }
    if (!player.isValid || player.dimension.id !== from) return;
    if (!ok) {
      player.setDynamicProperty("underworld:ready", 0);
      try {
        player.startItemCooldown(CFG.rock, 0);
      } catch {}
      return tell(player, "§cEl Underworld no responde. Inténtalo de nuevo.");
    }
    const now = player.location;   // the last position in the Overworld is the way back
    player.setDynamicProperty("underworld:back", JSON.stringify({ x: now.x, y: now.y, z: now.z }));
    await enter(player, now);
  }
  player.playSound("portal.travel", { volume: 0.35 });
}

world.afterEvents.itemUse.subscribe(({ source: player, itemStack }) => {
  if (itemStack?.typeId !== CFG.rock || player?.typeId !== "minecraft:player") return;
  const dimId = player.dimension.id;
  if (dimId !== DIM && dimId !== OVERWORLD) return tell(player, "§7La roca no reacciona en esta dimensión.");
  if (traveling.has(player.id)) return;
  const left = (player.getDynamicProperty("underworld:ready") ?? 0) - Date.now();
  if (left > 0 && left <= CFG.cooldown * 1000)
    return tell(player, `§7La roca aún está agotada: ${Math.ceil(left / 1000)} s`);
  player.setDynamicProperty("underworld:ready", Date.now() + CFG.cooldown * 1000);
  try {
    player.startItemCooldown(CFG.rock, CFG.cooldown * 20);
  } catch {}
  traveling.add(player.id);
  trip(player, dimId === DIM)
    .catch((e) => console.warn(`[Underworld] viaje fallido: ${e}`))
    .finally(() => traveling.delete(player.id));
});
